<div class="page-header"><div><h1><?=e($title)?></h1><p class="sub">Controleer de ontvangers en inhoud voor je verstuurt.</p></div><a class="nav-link" href="<?=e(url('mail/drafts'))?>"><?=icon('arrowLeft')?>Concepten</a></div>
