<div class="card"><dl class="detail-list"><div><dt>Account</dt><dd><?=e(account_get((int)$draft['account_id'])['label'])?></dd></div><div><dt>Aan</dt><dd><?=e(implode(', ',$draft['recipients']))?></dd></div><?php foreach(['cc'=>'Cc','bcc'=>'Bcc'] as $key=>$label):if(!$draft[$key])continue;?><div><dt><?=$label?></dt><dd><?=e(implode(', ',$draft[$key]))?></dd></div><?php endforeach;?><div><dt>Onderwerp</dt><dd><?=e($draft['subject'])?></dd></div></dl><div class="divider"></div><div class="mail-body"><?=e($draft['body'])?></div><?php foreach($draft['attachments'] as $a):?><p class="hint">Bijlage: <?=e($a['filename'])?></p><?php endforeach;?></div>
