<details class="card danger-details"><summary>Concept verwijderen</summary><form method="post" action="<?=e(url('mail/drafts/'.$draft['id'].'/delete'))?>" data-loading><?=csrf_field()?><label class="checkbox-row"><input type="checkbox" name="confirmed" value="1" required>Verwijder dit lokale concept</label><button class="btn btn-danger" type="submit">Verwijderen</button></form></details>
<?php elseif(!$accounts):?><div class="card empty-state"><div class="empty-state-icon"><?=icon('mail')?></div><h2>Voeg eerst een mailaccount toe</h2><p>Ga naar <a href="<?=e(url('mail/accounts'))?>">Mailaccounts</a> om een afzender te koppelen.</p></div><?php else:?>
<form method="post" action="<?=e(url('mail/compose'))?>" enctype="multipart/form-data" class="card" data-loading><?=csrf_field()?>
<?php if(!empty($input['draft_id'])):?><input type="hidden" name="draft_id" value="<?=(int)$input['draft_id']?>"><?php endif;?>
<?php if($reply):?><input type="hidden" name="reply_uid" value="<?=(int)$reply['uid']?>"><input type="hidden" name="reply_validity" value="<?=(int)$reply['uidvalidity']?>"><input type="hidden" name="reply_folder" value="<?=e($reply['folder'])?>"><?php endif;?>
<div class="field"><label for="account_id">Versturen vanuit</label><select id="account_id" name="account_id" <?=!empty($input['draft_id'])?'disabled':''?>><?php foreach($accounts as $a):?><option value="<?=(int)$a['id']?>" <?=(int)($input['account_id']??$reply['account_id']??0)===(int)$a['id']?'selected':''?>><?=e($a['label'].' · '.$a['email'])?></option><?php endforeach;?></select></div>
<div class="field"><label for="to">Aan</label><input id="to" name="to" value="<?=e($input['to']??implode(', ',$reply['reply_to']??[]))?>" placeholder="naam@voorbeeld.nl" required><p class="hint">Scheid meerdere adressen met een komma.</p></div>
