<div class="field"><label for="attachment">Bijlage (optioneel)</label><input id="attachment" name="attachment" type="file"><p class="hint">Maximaal 5 MB.</p></div>
<?php if(!empty($input['draft_id'])):?><p class="hint">Bestaande bijlagen blijven bewaard. Een nieuwe bijlage wordt toegevoegd.</p><?php endif;?><button class="btn btn-primary" type="submit"><?=icon('check')?>Concept opslaan</button>
</form>
<?php endif;?>
